export function getTranslatedShacmanSparePartDescription(name: string, language: string = 'zh'): string {
  // Try to get from detailed translations first
  const detailedTranslations = getTranslatedShacmanSparePartDetails(name, language);
  if (detailedTranslations) {
    return detailedTranslations;
  }
  
  // Fallback to generic description
  const genericDesc = 'Shacman part. Replace every 500-1000 hours or based on fluid analysis results.';
  const translations = shacmanDescriptionTranslations[genericDesc];
  if (translations) {
    return translations[language as keyof typeof translations] || genericDesc;
  }
  
  return '';
}

